MAP
FONTSET "fonts.lst"
IMAGETYPE png
MAXSIZE 4000
SIZE 800 800
EXTENT -20000000 -20000000 20000000 20000000
UNITS meters
IMAGECOLOR 153 179 204
WEB
   METADATA
      "ows_enable_request" "*"
      "wms_srs" "EPSG:900913 EPSG:4326 EPSG:3857 EPSG:28992"
      "labelcache_map_edge_buffer" "-10"
      "wms_title" "OpenStreetMap"
   END
END
DEBUG 1
PROJECTION
   "init=epsg:3857"
END
OUTPUTFORMAT
  NAME "png_bw"
  DRIVER "AGG/PNG"
  MIMETYPE "image/png;mode=8bit,grayscale"
  IMAGEMODE RGB
  EXTENSION "png"
  TRANSPARENT FALSE
  FORMATOPTION "PALETTE=grey.txt"
  FORMATOPTION "PALETTE_FORCE=on"
END
LAYER
   TYPE POLYGON
   STATUS ON
   GROUP "default"
   DEBUG 1
   NAME "land0"
   PROCESSING "APPROXIMATION_SCALE=full"
   PROJECTION
       "init=epsg:3857"
   END
   MINSCALEDENOM 332808204
   MAXSCALEDENOM 99999999999
   COMPOSITE
     OPACITY 100
   END # COMPOSITE
   DATA "data/simplified_land_polygons"
   CLASS
       STYLE
           COLOR 242 239 233
       END
   END
END
LAYER
    STATUS ON
    PROJECTION
        "init=epsg:3857"
    END
    GROUP "default"
    NAME "buildings0"
    TYPE POLYGON
    CONNECTIONTYPE postgis
    CONNECTION "host=postgis dbname=osm user=osm password=osm port=5432"
    EXTENT -20000000 -20000000 20000000 20000000
    DATA "geometry from (select geometry,osm_id, name as name from prod.osm_buildings) as foo using unique osm_id using srid=3857"
    LABELITEM "name"
    PROCESSING "LABEL_NO_CLIP=ON"
    PROCESSING "CLOSE_CONNECTION=DEFER"
    MAXSCALEDENOM 99999999999
    MINSCALEDENOM 332808204
    COMPOSITE
        OPACITY 100
    END # COMPOSITE
    CLASS
      STYLE
         COLOR "#bbbbbb"
         OPACITY 50
      END
      STYLE
         OUTLINECOLOR "#333333"
         WIDTH 0
      END
   END
END
LAYER
   GROUP "default"
   STATUS ON
   MAXSCALEDENOM 99999999999
   MINSCALEDENOM 332808204
   TYPE LINE
   NAME "borders0"
   PROJECTION
     "init=epsg:4326"
   END
   COMPOSITE
     OPACITY 100
   END # COMPOSITE
   DATA "data/boundaries.shp"
   CLASS
      STYLE
         WIDTH 0.5
         COLOR "#CDCBC6"
      END
   END
END
