    GROUP "default"
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=postgis dbname=osm user=osm password=osm port=5432"
    EXTENT -20000000 -20000000 20000000 20000000
    COMPOSITE
      OPACITY 100
    END # COMPOSITE
    DATA "geometry from (select geometry ,osm_id, type, name as name from prod.osm_landusages_gen00)            as foo using unique osm_id using srid=3857"
    PROCESSING "LABEL_NO_CLIP=ON"
    PROCESSING "CLOSE_CONNECTION=DEFER"
    MAXSCALEDENOM 41601025
    MINSCALEDENOM 20800512
    CLASSITEM "type"
    LABELITEM "name"
    CLASS
       EXPRESSION {forest,wood}
       STYLE
          COLOR 203 216 195
       END
    END
    CLASS
       EXPRESSION 'residential'
       STYLE
          COLOR 242 239 233
       END
   END
    CLASS
      EXPRESSION 'parking'
      STYLE
        COLOR "#eeeeee"
      END
    END
    CLASS
      EXPRESSION 'commercial'
      STYLE
        COLOR "#f2dad9"
      END
    END
    CLASS
      EXPRESSION 'industrial'
      STYLE
        COLOR 209 208 205
      END
    END
    CLASS
        EXPRESSION {park,golf_course}
        STYLE
            COLOR 181 210 156
        END
    END
    CLASS
        EXPRESSION 'cemetery'
        STYLE
          COLOR "#d1d1d1"
        END
    END
   CLASS
      EXPRESSION 'pedestrian'
      STYLE
         COLOR 250 250 245
      END
   END
    CLASS
        EXPRESSION 'hospital'
        STYLE
            COLOR 229 198 195
        END
    END
    CLASS
        EXPRESSION {school,college,university}
        STYLE
            COLOR 222 210 172
        END
    END
    CLASS
      EXPRESSION {sports_center,stadium,pitch}
      STYLE
          COLOR "#DED1AB"
      END
    END
END
