    CONNECTION "host=postgis dbname=osm user=osm password=osm port=5432"
    EXTENT -20000000 -20000000 20000000 20000000
    DATA "geometry from (select osm_id,CASE WHEN oneway=-1 THEN ST_Reverse(geometry) ELSE geometry END as geometry,name as name,ref,type,oneway,bridge,tunnel,coalesce(service,'') as service from prod.osm_roads where oneway in (1,-1) and st_length(geometry) > 50 order by z_order asc, st_length(geometry) asc) as foo using unique osm_id using srid=3857"
