SYMBOL
 name "citycircle"
 type ellipse
 points 1 1 end
 filled true
END
SYMBOL
 name "oneway_arrow"
 type vector
 points 13 0 7 -3 7 -0.5 0 -0.5 0 0.5 7 0.5 7 3 13 0 end
 filled true
 anchorpoint 0.5 0.5
END
